import{_ as e,o as s,c as o,ag as i}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Repair Station","description":"","frontmatter":{},"headers":[],"relativePath":"es/repair-station/index.md","filePath":"es/repair-station/index.md"}'),r={name:"es/repair-station/index.md"};function n(t,a,c,l,p,d){return s(),o("div",null,[...a[0]||(a[0]=[i(`<h1 id="repair-station" tabindex="-1">Repair Station <a class="header-anchor" href="#repair-station" aria-label="Permalink to &quot;Repair Station&quot;">​</a></h1><p>Entras con el vehículo en una estación de reparación, eliges un servicio y el vehículo se repara al momento: motor, carrocería y neumáticos, con sonido y chispas. El precio sigue los daños, así que un coche rayado paga menos que un siniestro total. Las estaciones se colocan en el juego y cada ajuste se edita en el juego.</p><p>El complemento de pago <a href="/es/repair-station-business/">Repair Station Business</a> permite a los jugadores comprar estaciones, abastecerlas de piezas y cobrar la caja.</p><h2 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to &quot;Características&quot;">​</a></h2><ul><li><strong>Tres servicios de serie</strong>: arreglo rápido (motor), chapa (carrocería y neumáticos), reparación completa. El nombre, el precio, la duración y las partes reparadas se pueden cambiar. Consulta <a href="/es/repair-station/settings">Ajustes</a>.</li><li><strong>Precio según los daños</strong>: el precio sigue los daños de las partes reparadas, hasta un porcentaje mínimo. Los vehículos intactos se rechazan.</li><li><strong>Editor de estaciones en el juego</strong>: crea una estación donde estás, mueve la zona de parada y un prop opcional con el teclado y guarda. Consulta <a href="/es/repair-station/stations">Estaciones</a>.</li><li><strong>Primero los mecánicos</strong>: las estaciones se cierran mientras haya suficientes mecánicos de servicio, y los jugadores los llaman a ellos.</li><li><strong>Justo y seguro</strong>: un vehículo por estación, comprobaciones del conductor y de la velocidad, pagos validados por el servidor. Una reparación cancelada se reembolsa en la cuenta cobrada.</li><li><strong>Descuentos por trabajo</strong>, un porcentaje de precio por estación y pago en efectivo, banco, o efectivo y luego banco.</li><li><strong>Todo en <code>/nay</code></strong>: servicios, precios, estaciones, trabajos de mecánico, blips con selector visual de icono y color.</li><li><strong>API HTTP y webhooks</strong>: historial de reparaciones, estadísticas y estaciones para tu web o tu bot, un mensaje de Discord por cada reparación. Consulta <a href="/es/repair-station/api">API y webhooks</a>.</li><li><strong>Ampliable</strong>: otro recurso puede cambiar los precios, cerrar estaciones y participar en cada reparación. Consulta <a href="/es/repair-station/api#extensions">Extensiones</a>.</li><li><strong>Seis idiomas</strong>: inglés, francés, español, portugués, polaco, alemán.</li></ul><h2 id="compatibilidad" tabindex="-1">Compatibilidad <a class="header-anchor" href="#compatibilidad" aria-label="Permalink to &quot;Compatibilidad&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detectados automáticamente.</li><li>Dependencias: oxmysql y <code>nay_lib</code> (incluido con tu compra).</li></ul><h2 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span></code></pre></div><p>Los pasos completos están en la página <a href="/es/getting-started">Primeros pasos</a>. Después date <code>nay_repair.config</code> (o <code>nay.admin</code>) y abre <code>/nay</code>. Tres estaciones vienen listas de serie: Hayes Autos, Sandy Shores y Paleto Bay.</p>`,10)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
